import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find top features by difference in means
    diffs = []
    for i, fid in enumerate(feats.ids):
        y0 = feats.x[feats.y == 0, i]
        y1 = feats.x[feats.y == 1, i]
        diff = np.mean(y1) - np.mean(y0)
        diffs.append((abs(diff), diff, fid))

    diffs.sort(reverse=True)
    top_fids = [fid for _, _, fid in diffs[:20]]

    # Remove near-duplicates
    to_remove = set()
    for i, fid1 in enumerate(top_fids):
        if fid1 in to_remove:
            continue
        for j, fid2 in enumerate(top_fids[i+1:], i+1):
            if fid2 in to_remove:
                continue
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], 
                              feats.x[:, feats.column(fid2)])[0,1]
            if abs(corr) >= 0.6:
                to_remove.add(fid2)

    clean_fids = [fid for fid in top_fids if fid not in to_remove]

    # Check for product terms
    best_product = None
    best_pval = 1.0
    for i, fid1 in enumerate(clean_fids[:10]):
        for j, fid2 in enumerate(clean_fids[i+1:], i+1):
            prod = feats.x[:, feats.column(fid1)] * feats.x[:, feats.column(fid2)]
            _, pval = stats.ttest_ind(prod[feats.y==1], prod[feats.y==0])
            if pval < best_pval:
                best_pval = pval
                best_product = (fid1, fid2)

    # If significant product term found, use it
    if best_pval < 0.05 and best_product:
        return Design(
            drivers=(best_product[0], best_product[1]),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={}
        )

    # Otherwise, return top single feature
    if clean_fids:
        return Design(
            drivers=(clean_fids[0],),
            columns=(clean_fids[0],),
            products=(),
            loadings={}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

